-- 124_ficha_producao_saude_estoque_v2.sql
-- Ficha do Gerenciamento de Produção: Saúde do Estoque v2 (objetivo atingido por linha). Aditiva e idempotente.

UPDATE mapa_modules SET
    detail = jsonb_set(detail, '{attention}', COALESCE(detail->'attention', '[]'::jsonb) || to_jsonb('Saúde do Estoque v2 (2026-11-18): a tela mostra o quão longe o estoque está do objetivo (o estoque ideal) e onde há estoque parado; não diz o que produzir (isso é a Demanda). Abas por tipo (Produtos, Kits, Coloração, Apoio), visão por linha com as sublinhas sob a principal e itens da linha ao clicar. O servidor devolve por item pct_objetivo (estoque futuro ÷ ideal, sem teto), distancia (estoque futuro − ideal, negativo conta como 0) e faixa (abaixo < 100%, no objetivo de 100% a 2×, acima de 2×, parado = sem giro com estoque; sem giro sem estoque e sem ideal sem estoque ficam fora da conta), e em por_tipo o resumo do tipo e por linha (proprio e total com sublinhas). Objetivo atingido = média de min(estoque futuro ÷ ideal, 1) dos itens com ideal > 0 que não são sem giro, para o excesso de um item não esconder a falta de outro; unidades que faltam = ideal − estoque nos abaixo, a mais = estoque − ideal nos acima de 2×, paradas = estoque dos parados. Cartões no topo são exceção do Edson só nesta tela. Valor em R$ fica para depois do custo de produtos (Administrativo)'::text)),
    updated_at = NOW()
WHERE module_key = 'producao'
  AND NOT (COALESCE(detail->'attention', '[]'::jsonb) @> to_jsonb('Saúde do Estoque v2 (2026-11-18): a tela mostra o quão longe o estoque está do objetivo (o estoque ideal) e onde há estoque parado; não diz o que produzir (isso é a Demanda). Abas por tipo (Produtos, Kits, Coloração, Apoio), visão por linha com as sublinhas sob a principal e itens da linha ao clicar. O servidor devolve por item pct_objetivo (estoque futuro ÷ ideal, sem teto), distancia (estoque futuro − ideal, negativo conta como 0) e faixa (abaixo < 100%, no objetivo de 100% a 2×, acima de 2×, parado = sem giro com estoque; sem giro sem estoque e sem ideal sem estoque ficam fora da conta), e em por_tipo o resumo do tipo e por linha (proprio e total com sublinhas). Objetivo atingido = média de min(estoque futuro ÷ ideal, 1) dos itens com ideal > 0 que não são sem giro, para o excesso de um item não esconder a falta de outro; unidades que faltam = ideal − estoque nos abaixo, a mais = estoque − ideal nos acima de 2×, paradas = estoque dos parados. Cartões no topo são exceção do Edson só nesta tela. Valor em R$ fica para depois do custo de produtos (Administrativo)'::text));
